function sliderServices() {
    var swiper = new Swiper('.services .mySwiper', {
        slidesPerView: 1,
        spaceBetween: 20,
        navigation: {
            nextEl: ".services .swiper-button-next",
            prevEl: ".services .swiper-button-prev",
        },
        breakpoints: {
            320: {
                spaceBetween: 10,
            },
            993: {
                spaceBetween: 20,
            },
        }
    });
}

function planGallery() {
    var swiper = new Swiper(".plan__images .mySwiper", {
        slidesPerView: 4,
        spaceBetween: 16,
        freeMode: true,
    });
    var swiper2 = new Swiper(".plan__images .mySwiper2", {
        spaceBetween: 16,
        slidesPerView: 1,
        thumbs: {
            swiper: swiper,
        },
        navigation: {
            nextEl: ".swiper-button-next",
            prevEl: ".swiper-button-prev",
        },
    });
}

function sliderPlanMob() {
    var swiper = new Swiper('.plan-mob .mySwiper', {
        slidesPerView: 1,
        spaceBetween: 20,
        effect: "fade",
        direction: "vertical",
    });

    // Флаг, что мы уже на последнем слайде
    let atLastSlide = false;

    swiper.on('slideChange', function () {
        if (swiper.isEnd) {
            atLastSlide = true; // дошли до последнего слайда
        } else {
            atLastSlide = false; // если листаем назад, сбрасываем флаг
        }
    });

    swiper.on('touchEnd', function () {
        // Если уже на последнем слайде и попытались листать дальше
        if (atLastSlide && swiper.touches.diff < 0) {
            // Удаляем контейнер
            document.querySelector('.plan-mob').remove();
        }
    });
}


$(document).ready(function () {
    sliderServices();
    planGallery();
    sliderPlanMob();

    // Menu
    $('.burger').click(function () {
        $('.menu').addClass('menu--active')
        $('body').addClass('fixed-body')
    })

    $('.menu__close').click(function () {
        $('.menu').removeClass('menu--active')
        $('body').removeClass('fixed-body')
    })

    // Header
    // let lastScrollTop = 0;
    // const header = $('#header');
    //
    // $(window).scroll(function() {
    //     let scrollTop = $(this).scrollTop();
    //
    //     if (scrollTop > lastScrollTop) {
    //         header.addClass('header-fixed');
    //     } else {
    //         header.removeClass('header-fixed');
    //     }
    //     lastScrollTop = scrollTop;
    // });

    // Btn-animation
    $(".btn-animation").mouseenter(function(e) {
        var $this = $(this);
        var $animation = $this.find(".circle");
        var offset = $this.offset();
        var x = e.pageX - offset.left;
        var y = e.pageY - offset.top;
        $animation.css({
            top: y + 'px',
            left: x + 'px'
        });
    });

    $(".btn-animation").mousemove(function(e) {
        var $this = $(this);
        var $animation = $this.find(".circle");
        var offset = $this.offset();
        var x = e.pageX - offset.left;
        var y = e.pageY - offset.top;
        $animation.css({
            top: y + 'px',
            left: x + 'px'
        });
    });

    // Form
    let isClicked = false;
    $('.form').on('submit', function(e) {
        e.preventDefault();

        isClicked = true;
        let allFilled = true;

        $(this).find('.form-group input').each(function() {
            const $input = $(this);
            const $formGroup = $input.closest('.form-group');

            if ($input.val().trim() === '') {
                $formGroup.addClass('form-group--active');
                allFilled = false;
            } else {
                $formGroup.removeClass('form-group--active');
            }
        });
    });
    $('.form-group input').on('input', function() {
        if (isClicked) {
            const $input = $(this);
            const $formGroup = $input.closest('.form-group');

            if ($input.val().trim() === '') {
                $formGroup.addClass('form-group--active');
            } else {
                $formGroup.removeClass('form-group--active');
            }
        }
    });

    // Up
    var t = $(".up");

    $(window).scroll(function() {
        if ($(window).scrollTop() > 300) {
            t.addClass("up--active");
        } else {
            t.removeClass("up--active");
        }
    });

    t.on("click", function(e) {
        e.preventDefault();
        $("html, body").animate({
            scrollTop: 0
        }, 300);
    });

    // Modal
    $("[data-modal]").click(function () {
        let modalId = $(this).attr("data-modal")

        openModal(modalId)
    })

    function openModal(modalId){
        $(`#${modalId}`).addClass("modal--active")
        $("body").addClass("fixed-body")
    }

    $(".modal").click(function () {
        closeModal()
    })

    $("._close-modal").click(function () {
        closeModal()
    })

    $(".modal__dialog").click(function (e) {
        e.stopPropagation()
    })

    function closeModal() {
        $('.modal').removeClass("modal--active")
        $("body").removeClass("fixed-body")
    }
});

function sliderMain() {
    const swiperContainer = document.querySelector('.main__mob');
    const nextSection = document.querySelector('.next-section');
    const swiper = new Swiper(".main__mob .mySwiper", {
        direction: "vertical",
        slidesPerView: 1,
        spaceBetween: 30,
        effect: "fade",
        mousewheel: false,
        touchStartPreventDefault: false,
        simulateTouch: true,
    });

    let wheelTimeout = null;

    swiperContainer.addEventListener('wheel', (e) => {
        const activeSlide = swiper.slides[swiper.activeIndex];
        const rect = activeSlide.getBoundingClientRect();
        const viewportHeight = window.innerHeight;

        const fullyVisible = Math.abs(rect.top) <= 2 && Math.abs(rect.bottom - viewportHeight) <= 2;

        if (!fullyVisible) {
            return;
        }

        if (wheelTimeout) {
            e.preventDefault();
            return;
        }

        const deltaY = e.deltaY;

        if (deltaY > 0) {
            if (swiper.isEnd) {
                if (nextSection) {
                    nextSection.scrollIntoView({ behavior: 'smooth' });
                    e.preventDefault();
                }
            } else {
                swiper.slideNext();
                e.preventDefault();
                wheelTimeout = setTimeout(() => {
                    wheelTimeout = null;
                }, 700);
            }
        } else if (deltaY < 0) {
            if (swiper.isBeginning) {
            } else {
                swiper.slidePrev();
                e.preventDefault();
                wheelTimeout = setTimeout(() => {
                    wheelTimeout = null;
                }, 700);
            }
        }
    }, { passive: false });

    let startY = 0;
    let isScrollingTouch = false;

    swiperContainer.addEventListener('touchstart', (e) => {
        startY = e.touches[0].clientY;
        isScrollingTouch = false;
    }, { passive: true });

    swiperContainer.addEventListener('touchmove', (e) => {
        const currentY = e.touches[0].clientY;
        const diffY = startY - currentY;

        if (swiper.isEnd) {
            if (diffY > 0) {
                swiper.allowTouchMove = false;
                isScrollingTouch = true;
            } else {
                swiper.allowTouchMove = true;
            }
        } else {
            swiper.allowTouchMove = true;
        }
    }, { passive: true });

    swiperContainer.addEventListener('touchend', () => {
        if (isScrollingTouch) {
            swiper.allowTouchMove = false;
        } else {
            swiper.allowTouchMove = true;
        }
    });

    swiper.on('slideChange', () => {
        swiper.allowTouchMove = true;
    });
}
sliderMain();
